<script>
    import { onMount, onDestroy } from "svelte";
    import { api } from "./lib/api.js";
    import { session, capabilities, toast } from "./lib/store.js";

    import ConnectView from "./views/ConnectView.svelte";
    import ExportView from "./views/ExportView.svelte";
    import VaultGate from "./components/VaultGate.svelte";
    import TreeView from "./components/TreeView.svelte";
    import AIChatPanel from "./components/AIChatPanel.svelte";
    import DataTable from "./components/DataTable.svelte";
    import IndexesTable from "./components/IndexesTable.svelte";
    import ForeignKeysTable from "./components/ForeignKeysTable.svelte";
    import Toaster from "./components/Toaster.svelte";
    import ResizeHandle from "./components/ResizeHandle.svelte";
    import SqlEditor from "./components/SqlEditor.svelte";
    import Modal from "./components/Modal.svelte";
    import Btn from "./components/ui/Btn.svelte";
    import Kbd from "./components/ui/Kbd.svelte";
    import SearchView from "./views/SearchView.svelte";

    let bootstrapping = true;
    let criticalSystemError = null;

    // Engines list (populated once on mount for defaultPort lookups etc.)
    let engines = [];

    // --- URL hash helpers ---
    function buildHash(ctx) {
        if (!ctx) return "";

        const parameters = {};

        if (ctx.db) parameters.db = ctx.db;
        if (ctx.table) parameters.table = ctx.table;
        if (ctx.mode) parameters.mode = ctx.mode;

        const p = new URLSearchParams(parameters);
        return "#" + p.toString();
    }

    function parseHash() {
        const raw = location.hash.slice(1);

        if (!raw) return null;

        try {
            const p = new URLSearchParams(raw);
            const db = p.get("db");
            const table = p.get("table");
            const mode = p.get("mode") || "data";
            const context = {};

            if (db) context.db = db;
            if (table) context.table = table;
            if (mode) context.mode = mode;

            return Object.keys(context).length > 0 ? context : null;
        } catch (_) {}

        return null;
    }

    function handlePopState() {
        const ctx = parseHash();
        if (ctx && $session) {
            loadOpenStateFromUrl(ctx);
        } else {
            tableContext = null;
            result = null;
        }
    }

    // --- DB picker + SQL editor state
    let sql = ``;
    let queryDb = "";
    let databases = [];
    let busy = false;
    let result = null; // { columns, rows, total, durationMs, isSelect, affected }
    let errors = []; // [{ message, time }] — persistent SQL error log, newest first
    let tableContext = null; // { db, table, mode } — set when browsing via tree
    let defaultDb = null;
    let sqlEditor;

    // Resizable panes
    let sqlPaneHeight = 220;
    let leftWidth = 220;
    let rightWidth = 260;

    // Modals
    let showExportModal = false;
    let showSearchModal = false;

    onMount(async () => {
        const systemCheck = await api.checkSystem();
        if (!systemCheck.ok) {
            toast("System check failed: " + systemCheck.error, "error");
            criticalSystemError = systemCheck.error;
            return;
        }

        window.addEventListener("popstate", handlePopState);

        try {
            const engRes = await api.getEngines();
            engines = engRes.engines || [];
        } catch (_) {
            /* non-fatal */
        }
        try {
            const r = await api.getSession();
            if (r.active) {
                session.set(r.active);
                // Restore state from URL after session is confirmed
                const ctx = parseHash();
                if (ctx) loadOpenStateFromUrl(ctx);
            }
        } catch (_) {
            /* no session — show connect view */
        } finally {
            bootstrapping = false;
        }
    });

    onDestroy(() => {
        window.removeEventListener("popstate", handlePopState);
    });

    // Reload databases whenever session becomes active
    $: if ($session) {
        loadDatabases();
        loadCapabilities();
    }

    async function loadDatabases() {
        try {
            const r = await api.listDatabases();
            databases = r.databases || [];
        } catch (_) {}
    }

    async function loadCapabilities() {
        try {
            const data = await api.getCapabilities();
            capabilities.set(data);
            // Set the welcome query for the SQL editor if it hasn't been manually changed
            if (!sql.trim()) {
                sql = data.welcomeQuery ?? "";
                sqlEditor?.setValue(sql);
            }
        } catch (_) {}
    }

    async function disconnect() {
        try {
            await api.disconnect();
            session.set(null);
            capabilities.set(null);
            databases = [];
            result = null;
            errors = [];
            tableContext = null;
            sql = "";
            history.replaceState(null, "", location.pathname);
            toast("Disconnected");
        } catch (e) {
            toast(e.message, "error");
        }
    }

    async function run() {
        if (!sql.trim() || busy) return;
        busy = true;
        tableContext = null; // manual SQL run clears table context
        try {
            const r = await api.runQuery(queryDb, sql);
            result = r;
            if (!r.isSelect) {
                toast(
                    `OK · ${r.affected} row${r.affected === 1 ? "" : "s"} affected · ${r.durationMs.toFixed(2)} ms`,
                    "success",
                );
            }
        } catch (e) {
            errors = [{ message: e.message, time: new Date() }, ...errors];
        } finally {
            busy = false;
        }
    }

    function onGlobalKeydown(e) {
        if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
            e.preventDefault();
            run();
        }
        if ((e.metaKey || e.ctrlKey) && e.key === "k") {
            e.preventDefault();
            if ($session) showSearchModal = true;
        }
        if ((e.metaKey || e.ctrlKey) && e.key === "e") {
            e.preventDefault();
            if ($session) showExportModal = true;
        }
    }

    function handleRunSql(e) {
        const { db, sql: newSql } = e.detail;
        sql = newSql;
        if (db) queryDb = db;
        run();
    }

    async function handleOpenTable(e) {
        const { db: tDb, table: tTbl, mode: tMode } = e.detail;
        const newCtx = { db: tDb, table: tTbl, mode: tMode };
        history.pushState(newCtx, "", buildHash(newCtx));
        await loadOpenStateFromUrl(newCtx);
    }

    async function handleToggleDb(e) {
        const { db } = e.detail;
        history.pushState(null, "", buildHash({ db }));
    }

    async function loadOpenStateFromUrl(ctx) {
        const { db: tDb, table: tTbl, mode: tMode } = ctx;
        queryDb = tDb;

        // Also populate the SQL editor for reference / manual tweaking
        const ioOpen = $capabilities?.identifierOpen ?? "`";
        const ioClose = $capabilities?.identifierClose ?? "`";
        function quoteIdent(name) {
            if (ioOpen === '"') return '"' + name.replace(/"/g, '""') + '"';
            if (ioOpen === "[") return "[" + name.replace(/]/g, "]]") + "]";
            return "`" + name.replace(/`/g, "``") + "`";
        }
        const qDb = quoteIdent(tDb);

        if (tTbl) {
            const qTbl = quoteIdent(tTbl);
            if (tMode === "data") {
                sql = `SELECT *\nFROM ${qDb}.${qTbl}\nLIMIT 100;`;
            } else if (tMode === "indexes") {
                sql = `-- Indexes on ${qDb}.${qTbl}`;
            } else if (tMode === "foreign-keys") {
                sql = `-- Foreign key constraints on ${qDb}.${qTbl}`;
            } else {
                const tmpl = $capabilities?.structureQueryTemplate;
                sql = tmpl
                    ? tmpl.replace("{db}", tDb).replace("{table}", tTbl)
                    : `SELECT * FROM ${qDb}.${qTbl};`;
            }
        } else {
            sql = `SHOW TABLES IN ${qDb};`;
        }

        // Push the new value into CodeMirror's internal state
        sqlEditor?.setValue(sql);

        busy = true;
        tableContext = null;
        result = null;

        if (tTbl) {
            try {
                const t0 = performance.now();
                if (tMode === "indexes") {
                    const r = await api.getTableIndexes(tDb, tTbl);
                    result = { indexes: r.indexes };
                    tableContext = { db: tDb, table: tTbl, mode: tMode };
                } else if (tMode === "foreign-keys") {
                    const r = await api.getTableForeignKeys(tDb, tTbl);
                    result = { outgoing: r.outgoing, incoming: r.incoming };
                    tableContext = { db: tDb, table: tTbl, mode: tMode };
                } else {
                    const r = await api.browseTable(tDb, tTbl);
                    const dt = performance.now() - t0;
                    result = {
                        columns: r.columns,
                        rows: r.rows,
                        affected: r.total,
                        isSelect: true,
                        durationMs: Math.round(dt * 100) / 100,
                    };
                    tableContext = { db: tDb, table: tTbl, mode: tMode };
                }
            } catch (e) {
                errors = [{ message: e.message, time: new Date() }, ...errors];
            } finally {
                busy = false;
            }
        } else {
            defaultDb = tDb;
            busy = false;
        }
    }

    async function handleRefresh() {
        if (!tableContext) return;
        busy = true;
        try {
            const t0 = performance.now();
            if (tableContext.mode === "indexes") {
                const r = await api.getTableIndexes(
                    tableContext.db,
                    tableContext.table,
                );
                result = { indexes: r.indexes };
            } else if (tableContext.mode === "foreign-keys") {
                const r = await api.getTableForeignKeys(
                    tableContext.db,
                    tableContext.table,
                );
                result = { outgoing: r.outgoing, incoming: r.incoming };
            } else {
                const r = await api.browseTable(
                    tableContext.db,
                    tableContext.table,
                );
                const dt = performance.now() - t0;
                result = {
                    columns: r.columns,
                    rows: r.rows,
                    affected: r.total,
                    isSelect: true,
                    durationMs: Math.round(dt * 100) / 100,
                };
            }
        } catch (e) {
            toast(e.message, "error");
        } finally {
            busy = false;
        }
    }

    function handleSqlResize({ detail }) {
        sqlPaneHeight = Math.max(
            100,
            Math.min(600, sqlPaneHeight + detail.delta),
        );
    }

    function handleLeftResize({ detail }) {
        leftWidth = Math.max(150, Math.min(500, leftWidth + detail.delta));
    }

    function handleRightResize({ detail }) {
        rightWidth = Math.max(150, Math.min(500, rightWidth - detail.delta));
    }
</script>

<svelte:window on:keydown={onGlobalKeydown} />

<Toaster />

{#if criticalSystemError}
    <div class="flex-1 flex items-center justify-center text-(--ink-3) mono">
        Critical system error: {criticalSystemError}
    </div>
{:else if bootstrapping}
    <div class="flex-1 flex items-center justify-center text-(--ink-3) mono">
        initializing…
    </div>
{:else if !$session}
    <div class="flex-1 overflow-y-auto">
        <VaultGate>
            <ConnectView />
        </VaultGate>
    </div>
{:else}
    <div class="h-full flex flex-col overflow-hidden">
        <!-- Topbar -->
        <header
            class="flex items-center px-4.5 h-11 shrink-0 bg-[rgba(10,12,10,0.85)] backdrop-blur-md border-b border-(--line) z-50"
        >
            <!-- Left: logo + session -->
            <div class="flex-1 flex items-center gap-3.5">
                <div class="flex gap-2 items-center">
                    <svg
                        class="w-6 h-6"
                        viewBox="0 0 512 512"
                        fill="none"
                        xmlns="http://www.w3.org/2000/svg"
                    >
                        <rect width="512" height="512" fill="#0A0C0A" />
